export const updateTransactionBodyDescriptionMax = 500;

export const updateTransactionBodyLinesItemAmountRegExp = new RegExp("^-?\\d+(\\.\\d{1,8})?$");
export const updateTransactionBodyNoteMin = 0;
export const updateTransactionBodyNoteMax = 1000;

export const updateTransactionBodySpreadMonthsMin = 2;
export const updateTransactionBodySpreadMonthsMax = 36;

export const updateTransactionBodyPlaceMin = 0;
export const updateTransactionBodyPlaceMax = 120;

export const UpdateTransactionBody = zod.object({
  accountId: zod.uuid().min(1),
  categoryId: zod.uuid().nullable(),
  type: zod.enum(["income", "expense"]),
  amount: zod.stringFormat("decimal", updateTransactionBodyAmountRegExp),
  date: zod.iso.date(),
  description: zod
    .string()
    .min(updateTransactionBodyDescriptionMin)
    .max(updateTransactionBodyDescriptionMax)
    .nullable(),
  lines: zod
    .array(
      zod.object({
        categoryId: zod.uuid().nullable(),
        amount: zod.stringFormat("decimal", updateTransactionBodyLinesItemAmountRegExp),
        description: zod.string().nullable(),
      }),
    )
    .nullable(),
  version: zod
    .int()
    .describe(
      "The version of the record you read. Any later change to the record gives it a new version.",
    ),
  tagIds: zod.array(zod.uuid()).nullable(),
  currency: zod
    .union([
      zod.null(),
      zod.enum([
        "eur",
        "usd",
        "gbp",
        "chf",
        "pln",
        "sek",
        "nok",
        "dkk",
        "czk",
        "huf",
        "ron",
        "isk",
        "try",
        "jpy",
        "cny",
        "hkd",
        "sgd",
        "krw",
        "inr",
        "idr",
        "myr",
        "php",
        "thb",
        "aud",
        "nzd",
        "cad",
        "mxn",
        "brl",
        "ils",
        "zar",
      ]),
    ])
    .optional(),
  refundOfTransactionId: zod.uuid().nullish(),
  note: zod.string().min(updateTransactionBodyNoteMin).max(updateTransactionBodyNoteMax).nullish(),
  spreadMonths: zod
    .int()
    .min(updateTransactionBodySpreadMonthsMin)
    .max(updateTransactionBodySpreadMonthsMax)
    .nullish()
    .describe(
      "Optional, from 2 to 36: count the amount in equal monthly slices over this many months, starting with the month of the date, or ending with it when spreadDirection is backward. A split spreads each line's share, and a refund spreads negative slices.",
    ),
  place: zod
    .string()
    .min(updateTransactionBodyPlaceMin)
    .max(updateTransactionBodyPlaceMax)
    .nullish()
    .describe(
      "Optional place of your own, such as a shop and its address, at most 120 characters. Stored only while the locations feature is on.",
    ),
  latitude: zod
    .number()
    .nullish()
    .describe(
      "Optional latitude from -90 to 90, sent together with longitude and kept to five decimals. Stored only while the locations feature is on.",
    ),
  longitude: zod
    .number()
    .nullish()
    .describe(
      "Optional longitude from -180 to 180, sent together with latitude and kept to five decimals.",
    ),
  spreadDirection: zod
    .union([zod.null(), zod.enum(["forward", "backward"])])
    .optional()
    .describe(
      "Optional, with spreadMonths: forward (the default) counts from the month of the date on, backward counts the months up to and including it, for a bill paid in arrears.",
    ),
});

export const updateTransactionResponseAmountRegExp = new RegExp("^-?\\d+(\\.\\d{1,8})?$");
export const updateTransactionResponseLinesItemAmountRegExp = new RegExp("^-?\\d+(\\.\\d{1,8})?$");
export const updateTransactionResponseReportingAmountRegExp = new RegExp("^-?\\d+(\\.\\d{1,8})?$");
export const updateTransactionResponseUnusualTwoTypicalAmountRegExp = new RegExp(
  "^-?\\d+(\\.\\d{1,8})?$",
);
export const updateTransactionResponseRefundedAmountRegExp = new RegExp("^-?\\d+(\\.\\d{1,8})?$");
export const updateTransactionResponseSharedExpenseTwoSharesItemAmountRegExp = new RegExp(
  "^-?\\d+(\\.\\d{1,8})?$",
);
export const updateTransactionResponseSharedExpenseTwoMyShareRegExp = new RegExp(
  "^-?\\d+(\\.\\d{1,8})?$",
);
export const updateTransactionResponseEnteredByMeDefault = false;
export const updateTransactionResponseContactSplitTwoOwnAmountRegExp = new RegExp(
  "^-?\\d+(\\.\\d{1,8})?$",
);
export const updateTransactionResponseContactSplitTwoSharesItemAmountRegExp = new RegExp(
  "^-?\\d+(\\.\\d{1,8})?$",
);

export const UpdateTransactionResponse = zod.object({
  id: zod.uuid(),
  accountId: zod.uuid(),
  categoryId: zod.uuid().nullable(),
  type: zod.enum(["income", "expense"]),
  amount: zod.stringFormat("decimal", updateTransactionResponseAmountRegExp),
  date: zod.iso.date(),
  description: zod.string().nullable(),
  source: zod.enum(["manual", "imported", "api"]),
  isSplit: zod.boolean(),
  createdAt: zod.iso.datetime({ offset: true }),
  lines: zod
    .array(
      zod.object({
        id: zod.uuid(),
        categoryId: zod.uuid().nullable(),
        amount: zod.stringFormat("decimal", updateTransactionResponseLinesItemAmountRegExp),
        description: zod.string().nullable(),
      }),
    )
    .nullable(),
  currency: zod.enum([
    "eur",
    "usd",
    "gbp",
    "chf",
    "pln",
    "sek",
    "nok",
    "dkk",
    "czk",
    "huf",
    "ron",
    "isk",
    "try",
    "jpy",
    "cny",
    "hkd",
    "sgd",
    "krw",
    "inr",
    "idr",
    "myr",
    "php",
    "thb",
    "aud",
    "nzd",
    "cad",
    "mxn",
    "brl",
    "ils",
    "zar",
  ]),
  reportingAmount: zod.stringFormat("decimal", updateTransactionResponseReportingAmountRegExp),
  tagIds: zod.array(zod.uuid()),
  attachmentCount: zod.int(),
  unusual: zod.union([
    zod.null(),
    zod.object({
      basis: zod.enum(["payee", "category"]),
      typicalAmount: zod.stringFormat(
        "decimal",
        updateTransactionResponseUnusualTwoTypicalAmountRegExp,
      ),
      factor: zod.number(),
      sampleSize: zod.int(),
    }),
  ]),
  unusualDismissed: zod.boolean(),
  version: zod.int(),
  debtPayment: zod
    .union([
      zod.null(),
      zod.object({
        id: zod.uuid(),
        debtId: zod.uuid(),
        debtName: zod.string(),
      }),
    ])
    .optional(),
  refundOf: zod
    .union([
      zod.null(),
      zod.object({
        id: zod.uuid(),
        date: zod.iso.date(),
        description: zod.string().nullable(),
      }),
    ])
    .optional(),
  refundedAmount: zod
    .stringFormat("decimal", updateTransactionResponseRefundedAmountRegExp)
    .nullish(),
  sharedExpense: zod
    .union([
      zod.null(),
      zod.object({
        id: zod.uuid(),
        householdId: zod.uuid(),
        householdName: zod.string(),
        method: zod.enum(["equal", "shares", "exact"]).describe("Equal, Shares or Exact."),
        shares: zod.array(
          zod.object({
            userId: zod.uuid(),
            name: zod.string(),
            weight: zod.int().nullable(),
            amount: zod.stringFormat(
              "decimal",
              updateTransactionResponseSharedExpenseTwoSharesItemAmountRegExp,
            ),
          }),
        ),
        myShare: zod.stringFormat(
          "decimal",
          updateTransactionResponseSharedExpenseTwoMyShareRegExp,
        ),
        amountDiffers: zod.boolean(),
      }),
    ])
    .optional(),
  note: zod.string().nullish(),
  payeeName: zod.string().nullish(),
  spreadMonths: zod.int().nullish(),
  spreadUntil: zod.union([zod.null(), zod.iso.date()]).optional(),
  place: zod.string().nullish(),
  latitude: zod.number().nullish(),
  longitude: zod.number().nullish(),
  groupId: zod.uuid().nullish(),
  enteredByMe: zod.boolean().default(updateTransactionResponseEnteredByMeDefault),
  receiptItem: zod
    .union([
      zod.null(),
      zod.object({
        name: zod.string(),
        warrantyUntil: zod.union([zod.null(), zod.iso.date()]),
      }),
    ])
    .optional(),
  contactSplit: zod
    .union([
      zod.null(),
      zod.object({
        id: zod.uuid(),
        method: zod.enum(["equal", "shares", "exact"]).describe("Equal, Shares or Exact."),
        ownWeight: zod.int().nullable(),
        ownAmount: zod
          .stringFormat("decimal", updateTransactionResponseContactSplitTwoOwnAmountRegExp)
          .nullable(),
        shares: zod.array(
          zod.object({
            contactId: zod.uuid(),
            name: zod.string(),
            weight: zod.int().nullable(),
            amount: zod.stringFormat(
              "decimal",
              updateTransactionResponseContactSplitTwoSharesItemAmountRegExp,
            ),
          }),
        ),
      }),
    ])
    .optional(),
  payee: zod.string().nullish(),
  spreadDirection: zod.union([zod.null(), zod.enum(["forward", "backward"])]).optional(),
  spreadFrom: zod.union([zod.null(), zod.iso.date()]).optional(),
});

/**
 * Answers "keep both" for every pair the duplicates=true filter currently finds with this transaction: each pair is stored and never offered again, so both rows leave the filter unless one of them still pairs with a third row. Changes neither transaction. To remove the extra row instead, delete it through DELETE /api/transactions/{id}. A transaction without a possible duplicate answers 204 and stores nothing.
 * @summary Keep a transaction and its possible duplicates
 */
export const KeepPossibleDuplicatesResponse = zod.void();

/**
 * Keeps the flag the background check stored but stops showing it: the ledger's unusual filter leaves the row out and the response reports unusualDismissed. The mark survives later edits of the transaction, so correcting a typo does not bring the flag back. Only an annotation; the transaction itself is not changed. Needs the unusualAmounts feature.
 * @summary Mark an unusual expense as not unusual
 */
export const DismissUnusualAmountResponse = zod.void();

/**
 * Removes the "not unusual" mark, so a stored flag shows in the ledger and in its unusual filter again. The undo of POST /api/transactions/{id}/unusual/dismiss. Needs the unusualAmounts feature.
 * @summary Mark an expense as unusual again
 */
export const RestoreUnusualAmountResponse = zod.void();
